def fuel_from_specs(apps, schema_editor):
    """Categories are now engine types. Recompute them for imported cars
    (plug-in hybrids used to be stored as electric) and drop 'other'."""
    def detect_fuel(drive):
        drive = drive.lower()
        if 'hybrid' in drive:
            return 'hybrid'
        if 'electric' in drive:
            return 'electric'
        if any(word in drive for word in ('lpg', 'cng', 'gas')):
            return 'gas'
        if 'diesel' in drive:
            return 'diesel'
        if 'petrol' in drive or 'combustion' in drive:
            return 'petrol'
        return ''

    Car = apps.get_model('cars', 'Car')
    Car.objects.filter(fuel='other').update(fuel='')
    for car in Car.objects.filter(source='hollmann').only('pk', 'specs'):
        drive = dict(tuple(row) for row in (car.specs or [])).get('Drive', '')
        fuel = detect_fuel(drive)
        if fuel:
            Car.objects.filter(pk=car.pk).update(fuel=fuel)


